Rules.InvariantScript:
Set(varIsNewBooking, IsBlank(varCurrentBooking.ID));
Set(varBkStart, Coalesce(varCurrentBooking.StartDate, Today()));
Set(varBkEnd, Coalesce(varCurrentBooking.EndDate, Today()));
Set(varPickTarget, "");
// A booking can cover several devices, so the choice is a collection, not a
// variable. An existing booking is one row and therefore one device; a new one
// starts from the asset we came from, if any.
Set(varBkSeed, Coalesce(varCurrentBooking.Title, varCurrentAsset.Titel, ""));
Clear(colBkAssets);
If(
    !IsBlank(varBkSeed),
    Collect(
        colBkAssets,
        {
            Id: LookUp(Equipment_Assets, Titel = varBkSeed).'Id (ID)',
            Value: varBkSeed
        }
    )
);
Set(varPickMonth, Date(Year(varBkStart), Month(varBkStart), 1))

If(
    IsBlank(LookUp(colBkAssets, Value = ThisItem.Titel)),
    Collect(
        colBkAssets,
        { Id: ThisItem.'Id (ID)', Value: ThisItem.Titel }
    )
);
Reset(txtBkAssetSearch)

If(
    IsBlank(LookUp(colBkAssets, Value = ThisItem.Titel)),
    Collect(
        colBkAssets,
        { Id: ThisItem.'Id (ID)', Value: ThisItem.Titel }
    )
);
Reset(txtBkAssetSearch)

If(
    IsBlank(LookUp(colBkAssets, Value = ThisItem.Titel)),
    Collect(
        colBkAssets,
        { Id: ThisItem.'Id (ID)', Value: ThisItem.Titel }
    )
);
Reset(txtBkAssetSearch)

If(
    IsEmpty(colBkAssets),
        "Select at least one asset.",
    varBkEnd < varBkStart,
        "The end date is before the start date.",
    CountRows(galConflicts.AllItems) > 0,
        "One of these assets is already booked for that period.",
    // The campus is derived from Equipment_Assets but stored in
    // Equipment_Bookings.TargetCampus, a separate choice column
    // with its own values. Without this the save fails at the
    // connector with nothing on screen explaining why.
    !IsBlank(lblBkCampusValue.Text)
        && IsBlank(
            LookUp(
                Choices(Equipment_Bookings.TargetCampus),
                Value = lblBkCampusValue.Text
            ).Value
        ),
        "Campus """ & lblBkCampusValue.Text & """ is missing from the bookings list's TargetCampus choices. Add it there first.",
    ""
)

If(
    !IsBlank(lblBookingValidation.Text),
        Notify(lblBookingValidation.Text, NotificationType.Warning),
    // Patch gets a literal record in each branch.
    // A new booking writes one row per device, so every row is an
    // ordinary asset booking: the conflict check, the device filter
    // and the calendar all keep working without a special case.
    // Editing touches the one row that was opened, so it stays single.
    If(
        varIsNewBooking,
        ForAll(
            colBkAssets As bk,
            Patch(
            Equipment_Bookings,
            Defaults(Equipment_Bookings),
            {
                Title:         bk.Value,
                StartDate:     varBkStart,
                EndDate:       varBkEnd,
                TargetCampus:  { Value: lblBkCampusValue.Text },
                ProjectCode:   Trim(txtBkProject.Text),
                BookingStatus: {
                    Value: First(Choices(Equipment_Bookings.BookingStatus)).Value
                },
                ReservedBy: {
                    '@odata.type': "#Microsoft.Azure.Connectors.SharePoint.SPListExpandedUser",
                    Claims: "i:0#.f|membership|" & Lower(User().Email),
                    DisplayName: User().FullName,
                    Email: User().Email,
                    Department: "",
                    JobTitle: "",
                    Picture: ""
                }
            }
            )
        ),
        Patch(
            Equipment_Bookings,
            // LookUp by ID, not the variable itself: a record carried in a global
            // variable loses its schema, and Patch rejects it as "a Record value,
            // but of a different schema".
            LookUp(Equipment_Bookings, ID = varCurrentBooking.ID),
            {
                Title:         First(colBkAssets).Value,
                StartDate:     varBkStart,
                EndDate:       varBkEnd,
                TargetCampus:  { Value: lblBkCampusValue.Text },
                ProjectCode:   Trim(txtBkProject.Text),
                BookingStatus: {
                    Value: Coalesce(
                        varCurrentBooking.BookingStatus.Value,
                        First(Choices(Equipment_Bookings.BookingStatus)).Value
                    )
                }
            }
        )
    );
    If(
        IsEmpty(Errors(Equipment_Bookings)),
        Notify(
            If(
                varIsNewBooking && CountRows(colBkAssets) > 1,
                CountRows(colBkAssets) & " bookings saved.",
                "Booking saved."
            ),
            NotificationType.Success
        );
        Set(varCurrentBooking, Blank());
        Navigate(scr_Bookings, ScreenTransition.Fade),
        Notify(
            "Save failed: " & Concat(Errors(Equipment_Bookings), Message, " | "),
            NotificationType.Error
        )
    )
)

Remove(Equipment_Bookings, varCurrentBooking);
Notify("Booking deleted.", NotificationType.Success);
Set(varCurrentBooking, Blank());
Navigate(scr_Bookings, ScreenTransition.Fade)

With(
    {
        first: DateAdd(
            varPickMonth,
            -(Weekday(varPickMonth, StartOfWeek.Monday) - 1),
            TimeUnit.Days
        )
    },
    ForAll(
        Sequence(42) As s,
        With(
            { d: DateAdd(first, s.Value - 1, TimeUnit.Days) },
            {
                CellDate: d,
                DayNum: Day(d),
                InMonth: Month(d) = Month(varPickMonth)
            }
        )
    )
)

If(
    varPickTarget = "start",
    Set(varBkStart, ThisItem.CellDate);
    // Keep the range sane: an end before the new start moves along.
    If(varBkEnd < ThisItem.CellDate, Set(varBkEnd, ThisItem.CellDate)),
    Set(varBkEnd, ThisItem.CellDate)
);
Set(varPickTarget, "")

If(
    varPickTarget = "start",
    Set(varBkStart, ThisItem.CellDate);
    // Keep the range sane: an end before the new start moves along.
    If(varBkEnd < ThisItem.CellDate, Set(varBkEnd, ThisItem.CellDate)),
    Set(varBkEnd, ThisItem.CellDate)
);
Set(varPickTarget, "")
